head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gAcptNo;
scwin.gMainFormCd;
scwin.gFormVer;
scwin.gIsurCd;
scwin.gPageSize = 50; //페이지 size
scwin.gTotalCnt = 0; //전체 row
scwin.gPageNoCnt = 10; //page 번호 개수
scwin.vCurrPageNo = 0; //현재 선택된 페이지번호

scwin.vScrenID = 'ULDSTF15100.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;
    $c.stf.setObjectValue(rdo_MKT_ID, scwin.gLdMktTp);
    if (scwin.gLdMktTp == '1' || scwin.gLdMktTp == '2') {
        $c.stf.showObj(panel_mkt, false);
        $c.cm.setColumnProp(grd_Grid, "MKT_NM", "Show", false);
        $c.cm.setColumnProp(grd_Grid_excel, "MKT_NM", "Show", false);
    }

    //  기간 from~ to  셋팅	
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue($c.ut.cGetMinusMonth(vCurDate.substring(0, 4), vCurDate.substring(4, 6), vCurDate.substring(6, 8), 1)); // 한달전 날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    //dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    dts_dep.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_dep.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_emp.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_emp.Reset();

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !감사종료보고서--;
목록검색;
클릭-- > function() {
    // 일자 체크
    if ($c.stf.getObjectValue(edt_FromDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if ($c.stf.getObjectValue(edt_ToDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    scwin.gDepCd = $c.stf.getObjectValue(cmb_TeamList);
    scwin.gEmpNo = $c.stf.getObjectValue(cmb_EmpList);
    fn_Search();
};
scwin.getChkValue = function(obj) {
    //return (obj.checked) ? "Y" : "N";
    if (obj.checked == true) {
        return obj.getValue();
    } else {
        return "0";
    }

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !감사종료보고서--;
클릭-- > function() {
    scwin.vCurrPageNo = 0;

    //var url = "/AuditClosedReport.do?method=listAuditClosedReport&inputMessageId=AUDITCLOSEDCOND_IN"
    var url = "/AuditClosedReport.do?method=pagingAuditClosedReport&inputMessageId=AUDITCLOSEDCOND_IN" + "&outputMessageId=AUDITCLOSEDLIST_OUT" + "&ISUR_NM_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate) + "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate) + "&DEP_CD=" + scwin.gDepCd + "&EMP_NO=" + scwin.gEmpNo + "&LD_MKT_TP=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&LAST_YN=" + scwin.getChkValue(chb_Last) + "&LIST_STAT=" + scwin.getChkValue(chb_ListStatCd) + "&ACNTCLS_MM=" + $c.stf.getObjectValue(cmb_month) + "&UP_DEP_CD=" + js_belngdepcd + "&PAGENO=" + scwin.vCurrPageNo + "&PAGESIZE=" + scwin.gPageSize + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    //alert("vCurrPageNo:"+vCurrPageNo +"   gPageSize:"+gPageSize);

    dts_DsclList.DataID = encodeURI(url);
    dts_DsclList.reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.PageNoCall = function(vPageNo) {
    //현재 선택한 페이지번호
    scwin.vCurrPageNo = vPageNo;
    var url = "/AuditClosedReport.do?method=pagingAuditClosedReport&inputMessageId=AUDITCLOSEDCOND_IN" + "&outputMessageId=AUDITCLOSEDLIST_OUT" + "&ISUR_NM_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate) + "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate) + "&DEP_CD=" + scwin.gDepCd + "&EMP_NO=" + scwin.gEmpNo + "&LD_MKT_TP=" + scwin.gLdMktTp + "&LAST_YN=" + scwin.getChkValue(chb_Last) + "&LIST_STAT=" + scwin.getChkValue(chb_ListStatCd) + "&ACNTCLS_MM=" + $c.stf.getObjectValue(cmb_month) + "&UP_DEP_CD=" + js_belngdepcd; + "&PAGENO=" + scwin.vCurrPageNo + "&PAGESIZE=" + scwin.gPageSize + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_DsclList.DataID = encodeURI(url);
    dts_DsclList.reset();
    $c.cm.ShowWin(grd_Grid);

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !감사종료보고서--;
엑셀다운로드-- > function() {
    var url = "/AuditClosedReport.do?method=listAuditClosedReport&inputMessageId=AUDITCLOSEDCOND_IN" + "&outputMessageId=AUDITCLOSEDLIST_OUT" + "&ISUR_NM_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate) + "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate) + "&DEP_CD=" + scwin.gDepCd + "&EMP_NO=" + scwin.gEmpNo + "&LD_MKT_TP=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&LAST_YN=" + scwin.getChkValue(chb_Last) + "&LIST_STAT=" + scwin.getChkValue(chb_ListStatCd) + "&ACNTCLS_MM=" + $c.stf.getObjectValue(cmb_month) + "&UP_DEP_CD=" + js_belngdepcd + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_07;
    dts_DsclList_excel.DataID = encodeURI(url);
    dts_DsclList_excel.reset();
};


// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gAcptNo = dts_DsclList.getCellData(eval(obj), "ACPT_NO");
    scwin.gMainFormCd = dts_DsclList.getCellData(eval(obj), "FORM_CD");
    scwin.gFormVer = dts_DsclList.getCellData(eval(obj), "FORM_VER");
    scwin.gIsurCd = dts_DsclList.getCellData(eval(obj), "ISUR_CD");

    //alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);

};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (colid == "DOC_TITLE") {
        $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, "R");
    } else if (colid == "PUBL_DDTM") {
        $c.stf.fn_OpenDisclAllList();
    } else if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.dts_DsclList_OnLoadError = function() {
    $c.stf.alert_error(dts_DsclList);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_DsclList_OnLoadCompleted = function(rowcount) {
    if (dts_DsclList.errorMsg) {
        $c.win.alert(dts_DsclList.errorMsg);
    } else {
        //수정해야될 부분
        //데이터가 로드 되면 다음 내용을 처리 하도록 한다.
        //최초 조회인 경우 전체 row cnt를 구한다.

        if (scwin.gPageSize != '0') {
            if (scwin.vCurrPageNo == 0) {
                scwin.vCurrPageNo = 1;
                scwin.gTotalCnt = dts_DsclList.getCellData(0, "TOTALCNT");
            }
        } else {
            scwin.gTotalCnt = rowcount;
        }
        //페이지번호개수,pagesize, 데이터전체cnt,패널id(page번호 표시),패널 width
        $c.stf.FillGridHeader(scwin.gPageNoCnt, scwin.gPageSize, scwin.gTotalCnt, panel_page, 743);
    }
    $c.cm.CloseWin(scwin.gTotalCnt, grd_Grid);
};
scwin.dts_DsclList_excel_OnLoadCompleted = function(rowcount) {
    $c.data.downloadGridViewExcel(grd_Grid_excel, "감사종료보고서 목록", "", "2");
};
scwin.btn_Excel_onclick = function() {
    fn_ExcelDownload();
};
scwin.btn_Search_onclick = function() {
    fn_CheckCond();
};
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    //setObjectValue(cmb_TeamList, js_dep_cd) ;		

};
scwin.dts_emp_OnLoadCompleted = function(rowcount) {
    //setObjectValue(cmb_EmpList, js_emp_no) ;	

};
scwin.cmb_TeamList_OnSelChange = function() {
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
    if (scwin.gDepCd == '') {
        $c.stf.setObjectValue(cmb_EmpList, '');
    }
    dts_emp.UseFilter = true;
    dts_emp.Filter();
    dts_emp.sort("DEP_CD", 0);
    //dts_emp.sort(); // W-Craft 주석처리 

};
scwin.dts_emp_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp.getCellData(row, "dep_cd") == scwin.gDepCd ||
            dts_emp.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_FromDate, edt_ToDate);
};
scwin.cmb_PerPage_OnSelChange = function() {
    var vPerPage = $c.cp.valueOfIndex(cmb_PerPage, "VALUE", cmb_PerPage.getSelectedIndex());
    scwin.gPageSize = vPerPage;
    //alert(gPageSize);	
    fn_Search();
};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.rdo_MKT_ID_OnSelChange = function() {
    //fn_SetCtrlByMktId();

};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    $c.stf.showObj(grd_Grid_excel, false);
    scwin.fn_SetCode();
    $c.stf.Combo_CBDataSet(cmb_PerPage);
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
};
